[{"order":1,"type":"heading","text":"Working with Complex Types (Arrays, Structs, Maps) in Apache Spark"},{"order":2,"type":"paragraph","text":"Apache Spark provides robust support for complex, nested data structures such as arrays, structs, and maps. These types allow you to model semi-structured data efficiently without losing the benefits of Spark's Catalyst optimizer and Tungsten execution engine."},{"order":3,"type":"subheading","text":"1. Arrays in Spark"},{"order":4,"type":"paragraph","text":"An Array type represents an ordered collection of elements of the same data type. You can create arrays using built-in functions like array() or collect_list(), and manipulate them using functions like element_at(), array_contains(), and explode()."},{"order":5,"type":"code","text":"import org.apache.spark.sql.functions._

val df = Seq(
  ("Alice", Seq("Scala", "Python", "Java")),
  ("Bob", Seq("Python", "R"))
).toDF("name", "languages")

// Check if array contains a specific value
val filteredDf = df.filter(array_contains($"languages", "Python"))

// Explode array into multiple rows
val explodedDf = df.withColumn("language", explode($"languages"))"},{"order":6,"type":"subheading","text":"2. Structs in Spark"},{"order":7,"type":"paragraph","text":"A Struct type represents a record with named fields, similar to a row in a relational database or a JSON object. Structs are ideal for grouping related attributes together. You can access nested fields using dot notation or the col() function."},{"order":8,"type":"code","text":"val dfStruct = Seq(
  ("Alice", ("New York", "NY", "10001")),
  ("Bob", ("San Francisco", "CA", "94107"))
).toDF("name", "address")

// Accessing nested struct fields
val extractedDf = dfStruct.select(
  $"name",
  $"address.city",
  $"address.zipcode"
)

// Creating a struct explicitly
val createdDf = dfStruct.withColumn("location", struct($"address.city", $"address.state"))"},{"order":9,"type":"subheading","text":"3. Maps in Spark"},{"order":10,"type":"paragraph","text":"A Map type represents a collection of key-value pairs, where keys and values must have consistent data types respectively. Maps are useful for dynamic attributes, metadata, or sparse matrices."},{"order":11,"type":"code","text":"val dfMap = Seq(
  ("Alice", Map("home" -> "555-0100", "work" -> "555-0199")),
  ("Bob", Map("home" -> "555-0200"))
).toDF("name", "phones")

// Accessing map values by key
val workPhoneDf = dfMap.withColumn("work_phone", $"phones"("work"))

// Get map keys and values
val keysDf = dfMap.select($"name", map_keys($"phones").as("phone_types"))"},{"order":12,"type":"subheading","text":"Best Practices for Complex Types"},{"order":13,"type":"bullet_point","text":"Use explode() with caution, as it can drastically increase your dataset row count and cause shuffle bottlenecks."},{"order":14,"type":"bullet_point","text":"Leverage Spark SQL native functions instead of User Defined Functions (UDFs) when manipulating complex types to maintain catalyst optimization."},{"order":15,"type":"bullet_point","text":"When writing to columnar formats like Parquet, deeply nested structs and arrays are encoded efficiently, but avoid unnecessary nesting depth to prevent memory overhead during schema resolution."}]
